uint64_t mod_mul(uint64_t a, uint64_t b) {
    uint64_t res = 0;
    while (b) {
        if (b & 1) res = (res + a) % MOD;
        a = (a + a) % MOD;
        b >>= 1;
    }
    return res;
}

uint64_t get_hash(int l, int r) {
    if (l > r) return 0;
    uint64_t h = hashS[r];
    if (l > 0) {
        uint64_t sub = mod_mul(hashS[l-1], powB[r-l+1]);
        h = (h + MOD - sub) % MOD;
    }
    return h;
}

