#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef unsigned long long ull;

#define MAXN 200005
#define MAXQ 200005
#define LOGN 20

typedef struct {
    int l, r, t, id;
} Query;

static char S[MAXN];
static int n, Q;

/* prefix hashes for each residue class modulo powers of two */
static ull *pref[LOGN];
static int lenClass[LOGN];
static ull basePow[MAXN];

/* random odd bases for each level */
static ull BASE[LOGN];

/* queries grouped by level */
static Query *bucket[LOGN];
static int bcnt[LOGN];

/* Fenwick tree */
static int bit[MAXN];

static inline void bit_add(int idx, int val) {
    for (; idx <= n; idx += idx & -idx) bit[idx] += val;
}
static inline int bit_sum(int idx) {
    int s = 0;
    for (; idx > 0; idx -= idx & -idx) s += bit[idx];
    return s;
}
static inline int bit_range(int l, int r) {
    if (l > r) return 0;
    return bit_sum(r) - bit_sum(l - 1);
}

static int cmp_query_r(const void *a, const void *b) {
    const Query *x = (const Query *)a;
    const Query *y = (const Query *)b;
    if (x->r != y->r) return x->r - y->r;
    return x->l - y->l;
}

static inline ull get_hash_level(int lev, int rem, int Lk, int Rk) {
    /* hash of sequence positions rem + k*2^lev, k in [Lk..Rk] */
    ull *p = pref[lev] + (size_t)rem * (lenClass[lev] + 1);
    return p[Rk + 1] - p[Lk] * basePow[Rk - Lk + 1];
}

static inline int eq_blocks(int lev, int a, int b, int cnt) {
    int mod = 1 << lev;
    int ra = (a - 1) & (mod - 1);
    int rb = (b - 1) & (mod - 1);
    if (ra != rb) return 0;
    int ka = (a - 1 - ra) >> lev;
    int kb = (b - 1 - rb) >> lev;
    ull ha = get_hash_level(lev, ra, ka, ka + cnt - 1);
    ull hb = get_hash_level(lev, rb, kb, kb + cnt - 1);
    return ha == hb;
}

/* find first mismatch between S[a + k*2^lev] and S[b + k*2^lev], k=0..cnt-1
   returns -1 if none, otherwise absolute position in original string of mismatch in first sequence */
static int first_mismatch_pos(int lev, int a, int b, int cnt) {
    if (eq_blocks(lev, a, b, cnt)) return -1;
    int lo = 0, hi = cnt - 1;
    while (lo < hi) {
        int mid = (lo + hi) >> 1;
        if (eq_blocks(lev, a, b, mid + 1)) lo = mid + 1;
        else hi = mid;
    }
    return a + (lo << lev);
}

int main(void) {
    if (scanf("%s", S + 1) != 1) return 0;
    n = (int)strlen(S + 1);
    scanf("%d", &Q);

    Query *allq = (Query *)malloc(sizeof(Query) * Q);
    char *ans = (char *)malloc(Q + 1);

    int maxLev = 0;
    while ((1 << (maxLev + 1)) <= n) maxLev++;

    srand(1234567 ^ (unsigned)time(NULL));
    for (int k = 0; k <= maxLev; k++) {
        BASE[k] = (((ull)rand() << 32) ^ rand() ^ ((ull)(k + 911382323) << 1)) | 1ULL;
    }

    basePow[0] = 1;
    ull commonBase = 146527ULL;
    for (int i = 1; i <= n; i++) basePow[i] = basePow[i - 1] * commonBase;

    for (int lev = 0; lev <= maxLev; lev++) {
        int mod = 1 << lev;
        lenClass[lev] = (n + mod - 1) / mod + 2;
        pref[lev] = (ull *)malloc(sizeof(ull) * (size_t)mod * (lenClass[lev] + 1));
        for (int r = 0; r < mod; r++) {
            ull *p = pref[lev] + (size_t)r * (lenClass[lev] + 1);
            p[0] = 0;
            int cnt = 0;
            for (int pos = r + 1; pos <= n; pos += mod) {
                p[cnt + 1] = p[cnt] * commonBase + (unsigned char)S[pos] + 1;
                cnt++;
            }
            while (cnt < lenClass[lev]) {
                p[cnt + 1] = p[cnt] * commonBase;
                cnt++;
            }
        }
    }

    for (int i = 0; i < Q; i++) {
        int l, r, t;
        scanf("%d %d %d", &l, &r, &t);
        allq[i].l = l;
        allq[i].r = r;
        allq[i].t = t;
        allq[i].id = i;

        if (t <= 0 || ((t & (t - 1)) != 0) || t > n) {
            ans[i] = 'N';
        } else {
            int lev = 0;
            while ((1 << lev) != t) lev++;
            if (bucket[lev] == NULL) {
                bucket[lev] = (Query *)malloc(sizeof(Query) * Q);
            }
            bucket[lev][bcnt[lev]++] = allq[i];
            ans[i] = '?';
        }
    }

    for (int lev = 0; lev <= maxLev; lev++) {
        if (bcnt[lev] == 0) continue;

        qsort(bucket[lev], bcnt[lev], sizeof(Query), cmp_query_r);

        memset(bit, 0, sizeof(int) * (n + 2));

        int step = 1 << lev;
        int *lastBad = (int *)malloc(sizeof(int) * (n + 2));
        for (int i = 0; i <= n + 1; i++) lastBad[i] = 0;

        int ptr = 0;
        for (int pos = step + 1; pos <= n; pos++) {
            if (S[pos] != S[pos - step]) {
                int residue = (pos - 1) & (step - 1);
                int idx = residue + 1;
                if (lastBad[idx]) bit_add(lastBad[idx], -1);
                lastBad[idx] = pos;
                bit_add(pos, 1);
            }

            while (ptr < bcnt[lev] && bucket[lev][ptr].r == pos) {
                int l = bucket[lev][ptr].l;
                int r = bucket[lev][ptr].r;
                int id = bucket[lev][ptr].id;

                int badcnt = bit_range(l + step, r);
                if (badcnt == 0) {
                    ans[id] = 'Y';
                } else if (badcnt > 2) {
                    ans[id] = 'N';
                } else {
                    /* Need exact check for one-edit possibility */
                    int len = r - l + 1;
                    if (len <= step + 1) {
                        ans[id] = 'Y';
                    } else {
                        int blocks = len - step; /* compare positions i and i+step for i=l..r-step */
                        int p = first_mismatch_pos(lev, l, l + step, blocks);
                        if (p == -1) {
                            ans[id] = 'Y';
                        } else {
                            /* skip one character candidate at p or p+step */
                            int ok = 0;

                            /* candidate change at p */
                            {
                                int leftCnt = (p - step - l) / step + 1;
                                if (p - step < l) leftCnt = 0;
                                int rightStart1 = p + step;
                                int rightStart2 = p + 2 * step;
                                int rightCnt = 0;
                                if (rightStart2 <= r) {
                                    rightCnt = (r - rightStart2) / step + 1;
                                }
                                if ((leftCnt == 0 || eq_blocks(lev, l, l + step, leftCnt)) &&
                                    (rightCnt == 0 || eq_blocks(lev, rightStart1, rightStart2, rightCnt))) {
                                    ok = 1;
                                }
                            }

                            /* candidate change at p+step */
                            if (!ok) {
                                int x = p + step;
                                int leftCnt = 0;
                                if (p - step >= l) leftCnt = (p - step - l) / step + 1;
                                int rightCnt = 0;
                                if (x + step <= r) rightCnt = (r - (x + step)) / step + 1;

                                if ((leftCnt == 0 || eq_blocks(lev, l, l + step, leftCnt)) &&
                                    (rightCnt == 0 || eq_blocks(lev, p, p + step, rightCnt))) {
                                    ok = 1;
                                }
                            }

                            ans[id] = ok ? 'Y' : 'N';
                        }
                    }
                }
                ptr++;
            }
        }

        while (ptr < bcnt[lev]) {
            int l = bucket[lev][ptr].l;
            int r = bucket[lev][ptr].r;
            int id = bucket[lev][ptr].id;
            if (r - l + 1 <= step + 1) ans[id] = 'Y';
            else {
                int badcnt = bit_range(l + step, r);
                if (badcnt == 0) ans[id] = 'Y';
                else if (badcnt > 2) ans[id] = 'N';
                else {
                    int len = r - l + 1;
                    int blocks = len - step;
                    int p = first_mismatch_pos(lev, l, l + step, blocks);
                    if (p == -1) ans[id] = 'Y';
                    else {
                        int ok = 0;
                        int leftCnt = (p - step - l) / step + 1;
                        if (p - step < l) leftCnt = 0;
                        int rightStart1 = p + step;
                        int rightStart2 = p + 2 * step;
                        int rightCnt = 0;
                        if (rightStart2 <= r) rightCnt = (r - rightStart2) / step + 1;
                        if ((leftCnt == 0 || eq_blocks(lev, l, l + step, leftCnt)) &&
                            (rightCnt == 0 || eq_blocks(lev, rightStart1, rightStart2, rightCnt))) ok = 1;

                        if (!ok) {
                            int x = p + step;
                            leftCnt = 0;
                            if (p - step >= l) leftCnt = (p - step - l) / step + 1;
                            rightCnt = 0;
                            if (x + step <= r) rightCnt = (r - (x + step)) / step + 1;
                            if ((leftCnt == 0 || eq_blocks(lev, l, l + step, leftCnt)) &&
                                (rightCnt == 0 || eq_blocks(lev, p, p + step, rightCnt))) ok = 1;
                        }
                        ans[id] = ok ? 'Y' : 'N';
                    }
                }
            }
            ptr++;
        }

        free(lastBad);
    }

    for (int i = 0; i < Q; i++) {
        puts(ans[i] == 'Y' ? "YES" : "NO");
    }

    return 0;
}

