public class Main {
    static final long BASE = 911382323L;
    static final long MOD = (1L << 61) - 1; // Large Mersenne prime for mod

    static long modMul(long a, long b) {
        long result = 0;
        a %= MOD;
        while (b > 0) {
            if ((b & 1) == 1) result = (result + a) % MOD;
            a = (a << 1) % MOD;
            b >>= 1;
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        int n = s.length();
        int q = Integer.parseInt(br.readLine());

        long[] pow = new long[n + 1];
        long[] hash = new long[n + 1];
        pow[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow[i] = modMul(pow[i - 1], BASE);
        }
        for (int i = 0; i < n; i++) {
            hash[i + 1] = (modMul(hash[i], BASE) + (s.charAt(i) - 'a' + 1)) % MOD;
        }

        PrintWriter out = new PrintWriter(System.out);
        while (q-- > 0) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int l = Integer.parseInt(st.nextToken()) - 1;
            int r = Integer.parseInt(st.nextToken()) - 1;
            int t = Integer.parseInt(st.nextToken());
            int len = r - l + 1;

            if (len == t) {
                out.println("YES");
                continue;
            }

            // Check if already periodic
            boolean already = true;
            for (int i = l; i + t <= r; i++) {
                if (s.charAt(i) != s.charAt(i + t)) {
                    already = false;
                    break;
                }
            }
            if (already) {
                out.println("YES");
                continue;
            }

            // Find mismatches using binary search and hashing
            int mismatchCount = 0;
            int pos = -1;
            int step = t;
            int start1 = l, start2 = l + t;

            while (start2 <= r) {
                // binary search to find first mismatch between the two sequences
                int lo = 0, hi = Math.min(r - start1, r - start2);
                int firstDiff = -1;
                while (lo <= hi) {
                    int mid = (lo + hi) / 2;
                    long h1 = getHash(hash, pow, start1, start1 + mid);
                    long h2 = getHash(hash, pow, start2, start2 + mid);
                    if (h1 == h2) {
                        lo = mid + 1;
                    } else {
                        firstDiff = mid;
                        hi = mid - 1;
                    }
                }
                if (firstDiff != -1) {
                    mismatchCount++;
                    if (mismatchCount > 1) break;
                    // skip this mismatch and continue from after it
                    start1 += firstDiff + 1;
                    start2 += firstDiff + 1;
                } else {
                    break;
                }
            }

            out.println(mismatchCount <= 1 ? "YES" : "NO");
        }
        out.flush();
    }

    static long getHash(long[] hash, long[] pow, int l, int r) {
        long result = (hash[r + 1] - modMul(hash[l], pow[r - l + 1]) + MOD) % MOD;
        return result;
    }
}

