import java.io.*;
import java.util.*;

public class Main {
    // Fast input
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static final long MOD1 = 1_000_000_007L;
    static final long MOD2 = 1_000_000_009L;
    static final long BASE1 = 911382323L;
    static final long BASE2 = 972663749L;

    static String s;
    static int n;
    static long[] pref1, pref2, pow1, pow2;

    static void buildHash() {
        pref1 = new long[n + 1];
        pref2 = new long[n + 1];
        pow1 = new long[n + 1];
        pow2 = new long[n + 1];
        pow1[0] = 1;
        pow2[0] = 1;
        for (int i = 0; i < n; i++) {
            int v = s.charAt(i);
            pref1[i + 1] = (pref1[i] * BASE1 + v) % MOD1;
            pref2[i + 1] = (pref2[i] * BASE2 + v) % MOD2;
            pow1[i + 1] = (pow1[i] * BASE1) % MOD1;
            pow2[i + 1] = (pow2[i] * BASE2) % MOD2;
        }
    }

    static long getHash1(int l, int r) { // [l, r)
        long res = (pref1[r] - pref1[l] * pow1[r - l]) % MOD1;
        if (res < 0) res += MOD1;
        return res;
    }

    static long getHash2(int l, int r) { // [l, r)
        long res = (pref2[r] - pref2[l] * pow2[r - l]) % MOD2;
        if (res < 0) res += MOD2;
        return res;
    }

    static boolean eq(int l1, int r1, int l2, int r2) {
        return getHash1(l1, r1) == getHash1(l2, r2) &&
               getHash2(l1, r1) == getHash2(l2, r2);
    }

    // Count mismatches between substring [l, r] and itself shifted by t:
    // compare S[l..r-t] with S[l+t..r]
    // Return >1 as soon as found.
    static int mismatchCountAtMostTwo(int l, int r, int t) {
        int len = r - l + 1;
        int cmpLen = len - t;
        if (cmpLen <= 0) return 0;

        int a = l;
        int b = l + t;
        int rem = cmpLen;
        int mismatches = 0;

        while (rem > 0) {
            if (eq(a, a + rem, b, b + rem)) break;

            int low = 0, high = rem;
            while (low < high) {
                int mid = (low + high + 1) >>> 1;
                if (eq(a, a + mid, b, b + mid)) low = mid;
                else high = mid - 1;
            }

            int samePrefix = low;
            if (samePrefix == rem) break;

            mismatches++;
            if (mismatches > 2) return mismatches;

            a += samePrefix + 1;
            b += samePrefix + 1;
            rem -= samePrefix + 1;
        }
        return mismatches;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        s = fs.next();
        n = s.length();
        buildHash();

        int q = fs.nextInt();
        StringBuilder out = new StringBuilder();

        while (q-- > 0) {
            int l = fs.nextInt() - 1;
            int r = fs.nextInt() - 1;
            int t = fs.nextInt();

            int len = r - l + 1;
            if (t >= len) {
                out.append("YES\n");
                continue;
            }

            int mism = mismatchCountAtMostTwo(l, r, t);

            // For period t, all equalities are along chains i, i+t, i+2t, ...
            // One changed character can fix all violations only if total mismatches
            // among adjacent pairs is 0, or 1, or exactly 2 and they share a common index.
            boolean ok;
            if (mism == 0 || mism == 1) {
                ok = true;
            } else if (mism > 2) {
                ok = false;
            } else {
                // mism == 2
                // Need to locate the two mismatch positions and check if they can be fixed by one char.
                int cmpLen = len - t;
                int a = l;
                int b = l + t;
                int rem = cmpLen;
                int[] x = new int[2];
                int[] y = new int[2];
                int cnt = 0;

                while (rem > 0 && cnt < 2) {
                    if (eq(a, a + rem, b, b + rem)) break;

                    int low = 0, high = rem;
                    while (low < high) {
                        int mid = (low + high + 1) >>> 1;
                        if (eq(a, a + mid, b, b + mid)) low = mid;
                        else high = mid - 1;
                    }
                    int samePrefix = low;
                    x[cnt] = a + samePrefix;
                    y[cnt] = b + samePrefix;
                    cnt++;

                    a += samePrefix + 1;
                    b += samePrefix + 1;
                    rem -= samePrefix + 1;
                }

                // One change can fix two mismatching edges iff they share an endpoint.
                ok = (x[0] == x[1]) || (x[0] == y[1]) || (y[0] == x[1]) || (y[0] == y[1]);
            }

            out.append(ok ? "YES\n" : "NO\n");
        }

        System.out.print(out.toString());
    }
}

#include <bits/stdc++.h>
using namespace std;

class SegTree {
public:
    int n;
    vector<long long> tree;
    vector<long long> base;
    long long mod;
    long long B;

    SegTree(const string &s, long long base_val, long long mod_val) {
        n = (int)s.size();
        B = base_val;
        mod = mod_val;
        base.resize(n+1);
        base[0] = 1;
        for (int i = 1; i <= n; i++) {
            base[i] = (base[i-1] * B) % mod;
        }
        tree.resize(4*n);
        build(1, 0, n-1, s);
    }

    void build(int idx, int l, int r, const string &s) {
        if (l == r) {
            tree[idx] = (s[l] - 'a' + 1) % mod;
            return;
        }
        int mid = (l+r)/2;
        build(idx*2, l, mid, s);
        build(idx*2+1, mid+1, r, s);
        tree[idx] = (tree[idx*2] * base[r-mid] + tree[idx*2+1]) % mod;
    }

    long long query(int idx, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return 0;
        if (ql <= l && r <= qr) {
            return (tree[idx] * base[qr - r]) % mod;
        }
        int mid = (l+r)/2;
        long long left = query(idx*2, l, mid, ql, qr);
        long long right = query(idx*2+1, mid+1, r, ql, qr);
        return (left + right) % mod;
    }

    long long get_hash(int l, int r) {
        return query(1, 0, n-1, l, r);
    }
};

