#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;

static ull splitmix64(ull x) {
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

struct SegTree {
    int n;
    vector<ull> tree;

    SegTree() {}
    SegTree(const vector<ull>& a) { build(a); }

    void build(const vector<ull>& a) {
        int sz = (int)a.size();
        n = 1;
        while (n < sz) n <<= 1;
        tree.assign(2 * n, 0);
        for (int i = 0; i < sz; ++i) tree[n + i] = a[i];
        for (int i = n - 1; i >= 1; --i) tree[i] = tree[i << 1] + tree[i << 1 | 1];
    }

    ull query(int l, int r) const { // inclusive
        if (l > r) return 0;
        l += n; r += n;
        ull res = 0;
        while (l <= r) {
            if (l & 1) res += tree[l++];
            if (!(r & 1)) res += tree[r--];
            l >>= 1; r >>= 1;
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    cin >> S;
    int N = (int)S.size();

    int Q;
    cin >> Q;

    vector<vector<int>> pos(26);
    for (int i = 0; i < N; ++i) pos[S[i] - 'a'].push_back(i);

    vector<SegTree> seg(26);
    for (int c = 0; c < 26; ++c) {
        vector<ull> arr(pos[c].size());
        for (int i = 0; i < (int)pos[c].size(); ++i) {
            arr[i] = splitmix64((ull)pos[c][i] + 1);
        }
        seg[c].build(arr);
    }

    auto getHash = [&](int c, int l, int r) -> ull {
        const auto& v = pos[c];
        int L = lower_bound(v.begin(), v.end(), l) - v.begin();
        int R = upper_bound(v.begin(), v.end(), r) - v.begin() - 1;
        if (L > R) return 0;
        return seg[c].query(L, R);
    };

    auto countIn = [&](int c, int l, int r) -> int {
        const auto& v = pos[c];
        return (int)(upper_bound(v.begin(), v.end(), r) - lower_bound(v.begin(), v.end(), l));
    };

    while (Q--) {
        int l, r, t;
        cin >> l >> r >> t;
        --l; --r;

        int len = r - l + 1;
        if (t >= len) {
            cout << "YES\n";
            continue;
        }

        bool ok = true;
        int badClasses = 0;
        int badEdges = 0;

        for (int c = 0; c < 26; ++c) {
            ull h1 = getHash(c, l, r - t);
            ull h2 = getHash(c, l + t, r);
            if (h1 != h2) {
                ok = false;
                ++badClasses;

                int cnt1 = countIn(c, l, r - t);
                int cnt2 = countIn(c, l + t, r);
                badEdges += abs(cnt1 - cnt2);
                if (badClasses > 2 || badEdges > 2) break;
            }
        }

        if (ok) {
            cout << "YES\n";
            continue;
        }

        cout << ((badClasses <= 2 && badEdges == 2) ? "YES\n" : "NO\n");
    }

    return 0;
}
